def pigeonhole_sort(a):

    if not a:
        return

    min_val = min(a)  
    max_val = max(a)  

    size = max_val - min_val + 1  

    holes = [0] * size

    for x in a:
        assert isinstance(x, int), "integers only please"
        holes[x - min_val] += 1

    i = 0
    for count in range(size):
        while holes[count] > 0:
            holes[count] -= 1
            a[i] = count + min_val
            i += 1

