def slowsort(sequence: list, start: int | None = None, end: int | None = None) -> None:

    if start is None:
        start = 0

    if end is None:
        end = len(sequence) - 1

    if start >= end:
        return

    mid = (start + end) // 2

    slowsort(sequence, start, mid)
